"""Signals of the fake Arduino: generated by ``spine_physiology`` and output as raw counts, as the firmware sends them.

It is the thinnest possible adapter between the ``spine_physiology`` generators (``synth_emg``, ``synth_imu``,
``synth_stretch``, which work on arrays and accept any time span) and the emulator: it builds the activity
(flexion repetitions of 3 s every 4 s), calls those generators and converts their physical output to counts.

- EMG: the module output (envelope, the gateway's hypothesis) in mV at the ADC input, to 10-bit counts with the
  5 V reference (``mV * 1023 / (vref * 1000)``), 0..1023.
- IMU: g and deg/s to int16 with the MPU-6050 sensitivity at ±4 g (8192 LSB/g) and ±500 dps (65.5 LSB/dps).
- Cord: ``synth_stretch`` already gives counts of the 10 kΩ divider with the 10-bit ADC, 1..1022.

The three signals share the same repetitions: the EMG contracts and the cord stretches in the same phase in which
gyro_x moves, which is what the backend counts as repetitions. The model parameters are those of
``physiology/configs/example-mission.yaml`` except what the hardware fixes (Uno ADC, MPU-6050, cord divider) and the
hypotheses that ``docs/sensor-sources.md`` documents as such.

No wall clock: the signal is a function of the seed and of the device time. It is generated in blocks of ``BLOCK_S`` s with
one random branch per block (``spine_physiology.rng``), so the cost is small and the same instant gives the same
counts whoever asks for them. Blocks start and end at rest, and the only state that passes from one block to the next, the
cord hysteresis residual, is carried over.
"""

from typing import Final

import numpy as np
from spine_contracts import AnatomicalPlane
from spine_contracts.models.domain.calibration_schema import BodyAxis
from spine_physiology import rng
from spine_physiology.config import (
    CordPoint,
    EmgAcquisition,
    EmgFilterMeta,
    EmgSignalConfig,
    ImuSignalConfig,
    Mounting,
    StretchCircuit,
    StretchSignalConfig,
    Xyz,
)
from spine_physiology.signals import Rep
from spine_physiology.signals.emg import activation_profile, synth_emg
from spine_physiology.signals.imu import angle_profile, synth_imu
from spine_physiology.signals.stretch import cord_length, synth_stretch

from spine_gateway.protocol import ImuSample

BLOCK_S: Final = 20
"""Duration of each block generated at once (a multiple of the repetition period and of the 100 ms batches)."""
BLOCK_MS: Final = BLOCK_S * 1000

REP_PERIOD_S: Final = 4.0
REP_DURATION_S: Final = 3.0
REP_OFFSET_S: Final = 0.5
"""One repetition of 3 s every 4 s, shifted by 0.5 s: the block (and the boot) start and end at rest."""
ROM_RANGE_DEG: Final = (30.0, 45.0)
"""Flexion range of each device (depending on the seed): the gyro peak is 1.25 * ROM dps."""
EMG_PEAK_COUNTS_RANGE: Final = (500.0, 700.0)
"""Envelope counts at the contraction peak (depending on the seed)."""

EMG_RATE_HZ: Final = 1000.0
IMU_RATE_HZ: Final = 100.0
CORD_RATE_HZ: Final = 20.0

ADC_BITS: Final = 10
ADC_VREF_V: Final = 5.0
ADC_MAX: Final = 2**ADC_BITS - 1
MV_PER_COUNT: Final = ADC_VREF_V * 1000.0 / ADC_MAX
"""EMG without gain (the gateway's ``emg_gain=1``): the ADC input is the module output."""
MEAN_ABS_UNIT_GAUSSIAN: Final = 0.7979
"""E|z| of a unit normal: the envelope (smoothed |x|) equals this times the signal RMS."""

ACCEL_LSB_PER_G: Final = 8192.0
GYRO_LSB_PER_DPS: Final = 65.5
INT16_MIN, INT16_MAX = -0x8000, 0x7FFF

REST_PCT_MVC: Final = 3.0
TREMOR_DPS: Final = 0.3
CORD_REST_LENGTH_MM: Final = 650.0

_SEED_MASK = (1 << 64) - 1

_EMG = EmgSignalConfig(
    sample_rate_hz=EMG_RATE_HZ,
    band_low_hz=20.0,
    band_high_hz=450.0,
    filter_order=4,
    noise_rms_mv=10.0,
    rest_pct_mvc=REST_PCT_MVC,
    fatigue_per_rep=0.0,
    fatigue_band_shift=0.3,
    deconditioning_pct_mvc_gain=0.0,
    deconditioning_fatigue_gain=0.0,
    acquisition=EmgAcquisition(adc_bits=ADC_BITS, vref_v=ADC_VREF_V, gain=1.0, input_pin="A0"),
    filter=EmgFilterMeta(highpass_hz=None, lowpass_hz=None, notch_hz=None),
    signal_kind="envelope",
    envelope_lowpass_hz=5.0,
    quantize_adc=False,
)

_IMU = ImuSignalConfig(
    sample_rate_hz=IMU_RATE_HZ,
    accel_noise_density_ug_rthz=400.0,
    gyro_noise_density_dps_rthz=0.005,
    accel_bias_g=Xyz(x=0.01, y=-0.005, z=0.002),
    gyro_bias_dps=Xyz(x=0.3, y=-0.2, z=0.1),
    accel_bias_max_g=Xyz(x=0.05, y=0.05, z=0.08),
    gyro_bias_max_dps=20.0,
    bias_drift_tau_s=1800.0,
    accel_bias_drift_sigma_g=0.002,
    gyro_bias_drift_sigma_dps=0.05,
    quantize_output=False,
    accel_range_g=4,
    gyro_range_dps=500,
    dlpf_hz=44.0,
    # Gravity on the sensor Z and sagittal flexion on gyro_x (left axis of the body).
    mounting=Mounting(sensor_x=BodyAxis.LEFT, sensor_y=BodyAxis.POSTERIOR, sensor_z=BodyAxis.CRANIAL),
    lever_arm_m=0.25,
    rom_loss_gain=0.0,
    pain_rom_gain=0.0,
    tremor_dps_per_unit=0.0,
)

_STRETCH = StretchSignalConfig(
    sample_rate_hz=CORD_RATE_HZ,
    curve=[
        CordPoint(resistance_ohm=5400.0, length_mm=585.0),
        CordPoint(resistance_ohm=6012.0, length_mm=650.0),
        CordPoint(resistance_ohm=6790.0, length_mm=731.0),
        CordPoint(resistance_ohm=7560.0, length_mm=812.0),
    ],
    circuit=StretchCircuit(adc_bits=ADC_BITS, vref_v=ADC_VREF_V, series_resistor_ohm=10000.0, input_pin="A1"),
    adc_noise_counts=1.0,
    hysteresis_tau_s=90.0,
    hysteresis_gain=0.15,
    band_recovering_threshold_mm=0.5,
    band_recovering_score=0.8,
    flexion_mm_per_deg=2.0,
    elongation_coupling=1.0,
    diurnal_loss_mm_at_1g=0.0,
    read_noise_ohm=5.0,
    repeat_dispersion_ohm=0.0,  # one offset per block would be a step every 20 s
    creep_fraction=0.02,
    creep_tau_s=90.0,
    lot_variation_fraction=0.0,
)


def _reps() -> tuple[Rep, ...]:
    return tuple(
        Rep(index=k + 1, start_s=k * REP_PERIOD_S + REP_OFFSET_S, end_s=k * REP_PERIOD_S + REP_OFFSET_S + REP_DURATION_S)
        for k in range(round(BLOCK_S / REP_PERIOD_S))
    )


def _counts(values: np.ndarray, low: int, high: int) -> np.ndarray:
    return np.clip(np.rint(values), low, high).astype(np.int64)


class _Block:
    """A block of ``BLOCK_S`` s of the three signals, already in counts."""

    def __init__(self, emg: np.ndarray, imu: np.ndarray, cord: np.ndarray, cord_residual_mm: float) -> None:
        self.emg = emg.tolist()
        self.imu = imu.tolist()
        self.cord = cord.tolist()
        self.cord_residual_mm = cord_residual_mm


class EmulatedSignals:
    """Counts of the three sensors per batch: ``emg``/``imu``/``cord`` receive the batch ``t0`` (ms since boot)."""

    def __init__(self, seed: int) -> None:
        self._seed = seed & _SEED_MASK
        profile = rng.generator(self._seed, "emulator", "profile")
        self._rom_deg = float(profile.uniform(*ROM_RANGE_DEG))
        peak_counts = float(profile.uniform(*EMG_PEAK_COUNTS_RANGE))
        self._mvc_rms_mv = peak_counts * MV_PER_COUNT / MEAN_ABS_UNIT_GAUSSIAN  # the envelope at 100 % MVC equals `peak_counts`
        self._index: int | None = None
        self._block: _Block | None = None
        self._carry: dict[int, float] = {}

    def emg(self, t0_ms: int) -> tuple[int, ...]:
        block, offset_ms = self._at(t0_ms)
        start = offset_ms
        return tuple(block.emg[start : start + 100])

    def imu(self, t0_ms: int) -> tuple[ImuSample, ...]:
        block, offset_ms = self._at(t0_ms)
        start = offset_ms // 10
        return tuple((a, b, c, d, e, f) for a, b, c, d, e, f in block.imu[start : start + 10])

    def cord(self, t0_ms: int) -> tuple[int, ...]:
        block, offset_ms = self._at(t0_ms)
        start = offset_ms // 50
        return tuple(block.cord[start : start + 2])

    def _at(self, t0_ms: int) -> tuple[_Block, int]:
        index, offset_ms = divmod(t0_ms, BLOCK_MS)
        if index != self._index or self._block is None:
            self._block = self._generate(index)
            self._index = index
            self._carry[index + 1] = self._block.cord_residual_mm
        return self._block, offset_ms

    def _generate(self, index: int) -> _Block:
        reps = _reps()
        emg_n, imu_n, cord_n = (round(BLOCK_S * r) for r in (EMG_RATE_HZ, IMU_RATE_HZ, CORD_RATE_HZ))

        pct = activation_profile(reps, peak_pct_mvc=100.0, rest_pct_mvc=REST_PCT_MVC, n_samples=emg_n, rate_hz=EMG_RATE_HZ)
        emg_mv = synth_emg(
            rng.generator(self._seed, "emulator", index, "emg"), _EMG, mvc_rms_mv=self._mvc_rms_mv, pct_mvc=pct, fatigue=np.zeros(emg_n), rate_hz=EMG_RATE_HZ
        )
        emg = _counts(emg_mv / MV_PER_COUNT, 0, ADC_MAX)

        angle = angle_profile(reps, rom_deg=self._rom_deg, n_samples=imu_n, rate_hz=IMU_RATE_HZ)
        channels = synth_imu(
            rng.generator(self._seed, "emulator", index, "imu"),
            _IMU,
            angle_deg=angle,
            plane=AnatomicalPlane.SAGITTAL,
            gravity_g=1.0,
            rate_hz=IMU_RATE_HZ,
            tremor_dps=TREMOR_DPS,
        )
        lsb = (ACCEL_LSB_PER_G,) * 3 + (GYRO_LSB_PER_DPS,) * 3
        imu = np.stack([_counts(channels[name] * k, INT16_MIN, INT16_MAX) for name, k in zip(_CHANNELS, lsb, strict=True)], axis=1)

        cord_angle = angle_profile(reps, rom_deg=self._rom_deg, n_samples=cord_n, rate_hz=CORD_RATE_HZ)
        length = cord_length(_STRETCH, rest_length_mm=CORD_REST_LENGTH_MM, elongation_mm=0.0, angle_deg=cord_angle, offset_mm=0.0)
        stretch = synth_stretch(
            rng.generator(self._seed, "emulator", index, "cord"),
            _STRETCH,
            length_mm=length,
            rest_length_mm=CORD_REST_LENGTH_MM,
            rate_hz=CORD_RATE_HZ,
            initial_residual_mm=self._carry.get(index, 0.0),
        )
        return _Block(emg, imu, stretch.adc_counts, float(stretch.residual_mm[-1]))


_CHANNELS = ("accel_x", "accel_y", "accel_z", "gyro_x", "gyro_y", "gyro_z")
